/*多线程URL探活，支持Get和Post请求，带进度条
by sunwu57
date:2025-08-26
updated: 添加多线程和进度条支持
updated: 添加认证
*/
yakit.AutoInitYakit()

targets = cli.Text("target", cli.setRequired(true), cli.setVerboseName("目标列表"))
targetList := str.SplitAndTrim(targets, "\n")
proxyStr = cli.String("proxy", cli.setVerboseName("代理"))
timeout=cli.Int("timeout", cli.setDefault(5), cli.setVerboseName("请求超时"))
threads = cli.Int("threads", cli.setDefault(120), cli.setVerboseName("线程数"))
cookieStr = cli.String("cookie", cli.setDefault("JSESSIONID=test;uuid=1;userid=admin"), cli.setVerboseName("Cookie"))
authStr = cli.String("auth", cli.setDefault("Bearer test"), cli.setVerboseName("Authorization"))

cli.check()

println(proxyStr)
if proxyStr != "" {
    yakit.Info("使用代理：%v", proxyStr)
    proxy = proxyStr
} else {
    proxy := "0"
}

yakit.Info("使用Cookie: %v", cookieStr)
yakit.Info("使用Authorization: %v", authStr)

yakit.EnableTable(
    "URL探活", 
    ["请求方式","url", "statuscode", "长度","title"], 
)

// 线程安全的输出函数
mutex = sync.NewMutex()
outputTable = func(method,url, statuscode, title, server, contentlength) {
    mutex.Lock()
    defer mutex.Unlock()

    data = make(map[string]any)
    data["请求方式"]=method
    data["url"] = url
    data["statuscode"] = statuscode
    data["title"] = title
    data["长度"] = contentlength
    yakit.TableData("URL探活", data)
}

func GetUrlInfo(url, proxy, cookie, auth) {
    packet = ""

    // 构建请求选项
    options = [poc.replaceRandomUserAgent()]
    if cookie != "" {
        options = append(options, poc.appendHeader("Cookie", cookie))
    }
    if auth != "" {
        options = append(options, poc.appendHeader("Authorization", auth))
    }
    if proxy != "0" {
        options = append(options, poc.proxy(proxy))
    }
options = append(options, poc.timeout(timeout))
    rsp, _ = poc.Get(url, options...)~
    packet = rsp.RawPacket

    statusCode = poc.GetStatusCodeFromResponse(packet)
    title = string(str.ExtractTitle(packet))
    server = poc.GetHTTPPacketHeader(packet, "Server")
    contentlength = len(poc.GetHTTPPacketBody(packet))
    return url, statusCode, title, server, contentlength
}

func PostUrlInfo(url, proxy, cookie, auth) {
    packet = ""

    // 构建请求选项
    options = [poc.replaceRandomUserAgent()]
    if cookie != "" {
        options = append(options, poc.appendHeader("Cookie", cookie))
    }
    if auth != "" {
        options = append(options, poc.appendHeader("Authorization", auth))
    }
    if proxy != "0" {
        options = append(options, poc.proxy(proxy))
    }
options = append(options, poc.timeout(timeout))
    rsp, _ = poc.Post(url, options...)~
    packet = rsp.RawPacket

    statusCode = poc.GetStatusCodeFromResponse(packet)
    title = string(str.ExtractTitle(packet))
    server = poc.GetHTTPPacketHeader(packet, "Server")
    contentlength = len(poc.GetHTTPPacketBody(packet))
    return url, statusCode, title, server, contentlength
}

// 构建最终目标列表
targetFinal = make([]string, 0, len(targetList) * 2)
for url in targetList {
    if !url.HasPrefix("https://") && !url.HasPrefix("http://") {
        targetFinal.Push("https://" + url)
        targetFinal.Push("http://" + url)
    } else {
        targetFinal.Push(url)
    }
}

// 计算总任务数（每个URL要进行Get和Post两次请求）
totalTasks = len(targetFinal) * 2
completedTasks = 0
progressMutex = sync.NewMutex()

// 更新进度条的函数
updateProgress = func() {
    progressMutex.Lock()
    defer progressMutex.Unlock()
    completedTasks++
    percent = float64(completedTasks) / float64(totalTasks)
    yakit.SetProgressEx("URL探活进度", percent)
}

yakit.Info("开始探活，目标数量：%d，总任务数：%d，线程数：%d", len(targetFinal), totalTasks, threads)

// 创建带大小限制的等待组
wg = sync.NewSizedWaitGroup(threads)

// 多线程处理
for index, element = range targetFinal {
    // Get请求任务
    wg.Add()
    go func(url) {
        defer wg.Done()
        defer updateProgress()

        try {
            r = GetUrlInfo(url, proxyStr, cookieStr, authStr)
            if len(r) == 0 {
                return
            } else {
                println("[GET] ", r[0], r[1], r[2], r[3], r[4])
                outputTable("Get", r[0], r[1], r[2], r[3], r[4])
            }
        } catch e {
            yakit.Warn("GET请求错误 %v: %v", url, e)
        }
    }(element)

    // Post请求任务
    wg.Add()
    go func(url) {
        defer wg.Done()
        defer updateProgress()

        try {
            r = PostUrlInfo(url, proxyStr, cookieStr, authStr)
            if len(r) == 0 {
                return
            } else {
                println("[POST]", r[0], r[1], r[2], r[3], r[4])
                outputTable("Post", r[0], r[1], r[2], r[3], r[4])
            }
        } catch e {
            yakit.Warn("POST请求错误 %v: %v", url, e)
        }
    }(element)
}

// 等待所有任务完成
wg.Wait()

yakit.Info("所有任务完成！共处理 %d 个目标，%d 个任务", len(targetFinal), totalTasks)
yakit.SetProgressEx("URL探活进度", 1.0)
